WITH access AS (SELECT EXISTS(SELECT 1 FROM calliope_apps.northstar_staff s WHERE s.email=$1 AND s.active AND s.role='dispatcher') AS authorized), reports AS (SELECT r.id,r.visit_id,coalesce(to_jsonb(r)->>'follow_up_reason','Not recorded') AS reason FROM calliope_apps.northstar_reports r WHERE (SELECT authorized FROM access)), reasons(ord,reason) AS (VALUES (0,'Not recorded'),(1,'No follow-up'),(2,'Parts needed'),(3,'Return diagnostic visit'),(4,'Customer unavailable'),(5,'Other')), buckets AS (SELECT c.ord,c.reason,count(r.id)::integer AS report_count FROM reasons c LEFT JOIN reports r ON r.reason=c.reason GROUP BY c.ord,c.reason) SELECT (SELECT authorized FROM access) AS authorized,'All saved reports; all submission dates; includes superseded reports and accepted visits; one count per report.'::text AS population,(SELECT count(*)::integer FROM reports) AS report_count,(SELECT count(DISTINCT visit_id)::integer FROM reports) AS visit_count,(SELECT count(*)::integer FROM reports WHERE reason='Not recorded') AS not_recorded_count,CASE WHEN (SELECT authorized FROM access) THEN (SELECT jsonb_agg(jsonb_build_object('reason',reason,'report_count',report_count) ORDER BY ord) FROM buckets) ELSE '[]'::jsonb END AS breakdown;
